// Who to send a customer's invoices to.
//
// This reads the customer straight from the application's customer store
// (context.customers). It no longer goes through lookupCustomer in
// ./customers.lookup.mjs.
//
// NOTE: I wrote this without seeing customers.lookup.mjs or the store's API.
// To make sure the handler still gives the same answers, check these points
// before merging:
//   1. The store is exposed as `context.customers` and has
//      `get(customerId)`. Rename these if the real accessor or method differs.
//   2. The way lookupCustomer handles a missing customer or a store error
//      matches the not-found branch below. Previously a missing customer
//      surfaced as a thrown error, either from lookupCustomer or from reading
//      properties of an empty result.
//   3. Any changes lookupCustomer made to name or email (trimming, casing,
//      fallbacks) are also done here. None are applied at present.
export async function billingContact(input, context) {
  const customer = await context.customers.get(input.customerId);
  if (!customer) {
    throw new Error(`Customer not found: ${input.customerId}`);
  }
  return { customerId: customer.customerId, name: customer.name, email: customer.email };
}
